package com.nexushr.controller; import com.nexushr.model.*;import com.nexushr.repo.*;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/performance") public class PerformanceController{final PerformanceReviewRepository r;final EmployeeRepository er;public PerformanceController(PerformanceReviewRepository r,EmployeeRepository e){this.r=r;er=e;} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @GetMapping public List<PerformanceReview> all(){return r.findAll();} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PostMapping public PerformanceReview create(@RequestBody PerformanceReview x){x.employee=er.findById(x.employee.id).orElseThrow();x.overallScore=(x.technicalSkills+x.communication+x.teamwork+x.productivity+x.leadership)/5;return r.save(x);} }
